export const privacyPolicyIntroHtml = "<p>\n            This Privacy Notice from Bohdan Bats (\"<b>I</b>\", \"<b>me</b>\", \"<b>my</b>\"), describes how and why I might access, collect, store, use, and/or share (\"process\") your personal information when you use my services (\"Services\"), including when you:\n            <ul>\n                <li>Download and use my mobile application (Principles: Habits for Goals), or any other application of ours that links to this Privacy Notice</li>\n                <li>Use Principles. A personalized app that aims to help users improve areas of their lives, achieve their mission and goals through habits, motivating reminders, and personalized artificial intelligence.</li>\n                <li>Engage with me in other related ways, including any sales, marketing, or events</li>\n            </ul>\n            <b>Questions or concerns?</b> Reading this Privacy Notice will help you understand your privacy rights and choices. I am responsible for making decisions about how your personal information is processed. If you do not agree with my policies and practices, please do not use my Services. If you still have any questions or concerns, please contact me at app@principles.top.\n        </p>";

