  {
    "id": "howToReviewUpdateDelete",
    "title": "15. HOW CAN YOU REVIEW, UPDATE, OR DELETE THE DATA I COLLECT FROM YOU?",
    "blocks": [
      {
        "type": "html",
        "html": "<p>Based on the applicable laws of your country or state of residence in the US, you may have the right to request access to the personal information I collect from you, details about how I have processed it, correct inaccuracies, or delete your personal information. You may also have the right to withdraw your consent to my processing of your personal information. These rights may be limited in some circumstances by applicable law. To request to review, update, or delete your personal information, please write me: app@principles.top.</p>"
      }
    ]
  },
  {
    "id": "accountDeletion",
    "title": "16. ACCOUNT DELETION",
    "blocks": [
      {
        "type": "html",
        "html": "<p>\n                Users have the right to delete their account at any time. The following methods are available:\n                <ul>\n                    <li>\n                        Via the website – to initiate account deletion, a user should visit the website and navigate to the\n                        <a href=\"/settings\">Settings</a> section. Within this section, a user will find the\n                        \"Delete Account\" option. To proceed, a user is required to enter account credentials and follow the\n                        on-screen instructions to confirm the deletion.\n                    </li>\n                    <li>\n                        Via the mobile app – to delete an account through the mobile application, a user must open the\n                        <a href=\"/settings\">Settings</a> section, tap on the \"Delete Account\" option,\n                        and follow the provided instructions to complete the process.\n                    </li>\n                </ul>\n            </p>"
      }
    ]
  }
